sealed class SessionException: kotlin.Exception() {
    
    class InvalidKeyLength(
        
        val `expected`: kotlin.UInt, 
        
        val `got`: kotlin.UInt
        ) : SessionException() {
        override val message
            get() = "expected=${ `expected` }, got=${ `got` }"
    }
    
    class InvalidRelayPublicKey(
        ) : SessionException() {
        override val message
            get() = ""
    }
    
    class InvalidNamespace(
        
        val `msg`: kotlin.String
        ) : SessionException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class PushFailed(
        
        val `msg`: kotlin.String
        ) : SessionException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class InvalidToken(
        ) : SessionException() {
        override val message
            get() = ""
    }
    
    class NotInGroup(
        ) : SessionException() {
        override val message
            get() = ""
    }
    
    class MemberNotFound(
        ) : SessionException() {
        override val message
            get() = ""
    }
    
    class GroupDestroyed(
        ) : SessionException() {
        override val message
            get() = ""
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SessionException> {
        override fun lift(error_buf: RustBuffer.ByValue): SessionException = FfiConverterTypeSessionError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeSessionError : FfiConverterRustBuffer<SessionException> {
    override fun read(buf: ByteBuffer): SessionException {
        

        return when(buf.getInt()) {
            1 -> SessionException.InvalidKeyLength(
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                )
            2 -> SessionException.InvalidRelayPublicKey()
            3 -> SessionException.InvalidNamespace(
                FfiConverterString.read(buf),
                )
            4 -> SessionException.PushFailed(
                FfiConverterString.read(buf),
                )
            5 -> SessionException.InvalidToken()
            6 -> SessionException.NotInGroup()
            7 -> SessionException.MemberNotFound()
            8 -> SessionException.GroupDestroyed()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SessionException): ULong {
        return when(value) {
            is SessionException.InvalidKeyLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`expected`)
                + FfiConverterUInt.allocationSize(value.`got`)
            )
            is SessionException.InvalidRelayPublicKey -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SessionException.InvalidNamespace -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is SessionException.PushFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is SessionException.InvalidToken -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SessionException.NotInGroup -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SessionException.MemberNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SessionException.GroupDestroyed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: SessionException, buf: ByteBuffer) {
        when(value) {
            is SessionException.InvalidKeyLength -> {
                buf.putInt(1)
                FfiConverterUInt.write(value.`expected`, buf)
                FfiConverterUInt.write(value.`got`, buf)
                Unit
            }
            is SessionException.InvalidRelayPublicKey -> {
                buf.putInt(2)
                Unit
            }
            is SessionException.InvalidNamespace -> {
                buf.putInt(3)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is SessionException.PushFailed -> {
                buf.putInt(4)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is SessionException.InvalidToken -> {
                buf.putInt(5)
                Unit
            }
            is SessionException.NotInGroup -> {
                buf.putInt(6)
                Unit
            }
            is SessionException.MemberNotFound -> {
                buf.putInt(7)
                Unit
            }
            is SessionException.GroupDestroyed -> {
                buf.putInt(8)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





